insert into public.subjects (slug, name, description, icon, status, sort_order)
insert into public.subject_categories (subject_id, category_id)
insert into public.questions (subject_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, tags, source, difficulty, status)
values
  ((select id from public.subjects where slug = 'hindi'), '''सूर्य'' का पर्यायवाची शब्द कौन-सा है?', 'निशाकर', 'हिमकर', 'सुधाकर', 'दिनकर', 'D', 'दिनकर का अर्थ है दिन करने वाला, अर्थात् सूर्य। बाकी तीनों चंद्रमा के पर्यायवाची हैं।', array['hindi', 'b-ed'], 'EntranceGo original', 'easy', 'published'),
  ((select id from public.subjects where slug = 'hindi'), '''अमृत'' का विलोम शब्द कौन-सा है?', 'मधु', 'जल', 'विष', 'दूध', 'C', 'अमृत का उल्टा विष है।', array['hindi', 'b-ed'], 'EntranceGo original', 'easy', 'published'),
  ((select id from public.subjects where slug = 'hindi'), '''कमल'' का पर्यायवाची शब्द कौन-सा है?', 'कुसुमाकर', 'पंकज', 'भ्रमर', 'मधुकर', 'B', 'पंकज (कीचड़ में जन्मा) कमल का पर्यायवाची है।', array['hindi', 'b-ed'], 'EntranceGo original', 'easy', 'published'),
  ((select id from public.subjects where slug = 'hindi'), '''राम ने खाना खाया'' — इस वाक्य में क्रिया कौन-सी है?', 'खाया', 'ने', 'खाना', 'राम', 'A', 'जिस शब्द से काम का होना पता चले वह क्रिया है: खाया।', array['hindi', 'b-ed'], 'EntranceGo original', 'easy', 'published'),
  ((select id from public.subjects where slug = 'hindi'), '''विद्यालय'' का सही संधि-विच्छेद क्या है?', 'विद्य + आलय', 'विद्या + लय', 'विद + आलय', 'विद्या + आलय', 'D', 'आ + आ = आ (दीर्घ संधि): विद्या + आलय = विद्यालय।', array['hindi', 'b-ed'], 'EntranceGo original', 'medium', 'published'),
  ((select id from public.subjects where slug = 'hindi'), '''हिमालय'' का सही संधि-विच्छेद क्या है?', 'हिम + आलय', 'हि + मालय', 'हिमा + लय', 'हिम + लय', 'A', 'अ + आ = आ (दीर्घ संधि): हिम + आलय = हिमालय।', array['hindi', 'b-ed'], 'EntranceGo original', 'medium', 'published'),
  ((select id from public.subjects where slug = 'hindi'), '''जो ईश्वर में विश्वास रखता हो'' — इसके लिए एक शब्द क्या है?', 'नास्तिक', 'आस्तिक', 'पुजारी', 'धार्मिक', 'B', 'ईश्वर में विश्वास रखने वाला आस्तिक कहलाता है; न रखने वाला नास्तिक।', array['hindi', 'b-ed'], 'EntranceGo original', 'medium', 'published'),
  ((select id from public.subjects where slug = 'hindi'), '''आँख का तारा'' मुहावरे का अर्थ क्या है?', 'आसमान का तारा', 'बहुत दूर का व्यक्ति', 'बहुत प्यारा', 'आँख का रोग', 'C', 'आँख का तारा होना = बहुत प्यारा होना।', array['hindi', 'b-ed'], 'EntranceGo original', 'medium', 'published'),
  ((select id from public.subjects where slug = 'hindi'), '''पुस्तक'' शब्द का बहुवचन क्या है?', 'पुस्तकाएँ', 'पुस्तकी', 'पुस्तको', 'पुस्तकें', 'D', 'स्त्रीलिंग अकारांत शब्द का बहुवचन -एँ लगाकर बनता है: पुस्तकें।', array['hindi', 'b-ed'], 'EntranceGo original', 'easy', 'published'),
  ((select id from public.subjects where slug = 'hindi'), '''सुंदर लड़की गा रही है'' — इस वाक्य में ''सुंदर'' कौन-सा पद है?', 'विशेषण', 'संज्ञा', 'क्रिया', 'सर्वनाम', 'A', 'सुंदर, संज्ञा (लड़की) की विशेषता बताता है, इसलिए विशेषण है।', array['hindi', 'b-ed'], 'EntranceGo original', 'easy', 'published'),
  ((select id from public.subjects where slug = 'hindi'), '''वह स्कूल जाता है'' — इस वाक्य में ''वह'' कौन-सा पद है?', 'संज्ञा', 'अव्यय', 'सर्वनाम', 'विशेषण', 'C', 'संज्ञा के स्थान पर आने वाला शब्द सर्वनाम कहलाता है।', array['hindi', 'b-ed'], 'EntranceGo original', 'easy', 'published'),
  ((select id from public.subjects where slug = 'hindi'), '''नीलकंठ'' में कौन-सा समास है?', 'बहुव्रीहि', 'द्विगु', 'अव्ययीभाव', 'द्वंद्व', 'A', 'नीला है कंठ जिसका, अर्थात् शिव: अन्य पद प्रधान होने से बहुव्रीहि समास।', array['hindi', 'b-ed'], 'EntranceGo original', 'hard', 'published'),
  ((select id from public.subjects where slug = 'english'), 'Choose the word closest in meaning to ''Brave''.', 'Timid', 'Careless', 'Lazy', 'Courageous', 'D', 'Brave means showing courage, so Courageous is the synonym.', array['english', 'b-ed'], 'EntranceGo original', 'easy', 'published'),
  ((select id from public.subjects where slug = 'english'), 'Choose the word opposite in meaning to ''Victory''.', 'Triumph', 'Success', 'Defeat', 'Win', 'C', 'Defeat is the opposite of victory.', array['english', 'b-ed'], 'EntranceGo original', 'easy', 'published'),
  ((select id from public.subjects where slug = 'english'), 'Fill in the blank with the correct article: He is ___ honest man.', 'no article', 'an', 'a', 'the', 'B', '''Honest'' begins with a vowel sound (the h is silent), so we use ''an''.', array['english', 'b-ed'], 'EntranceGo original', 'easy', 'published'),
  ((select id from public.subjects where slug = 'english'), 'What is the plural of ''child''?', 'children', 'childrens', 'childes', 'childs', 'A', '''Child'' has an irregular plural: children.', array['english', 'b-ed'], 'EntranceGo original', 'easy', 'published'),
  ((select id from public.subjects where slug = 'english'), 'Identify the noun in the sentence: ''The cat sleeps on the mat.''', 'sleeps', 'on', 'the', 'cat', 'D', '''Cat'' names an animal, so it is a noun (''mat'' is also a noun but is not offered).', array['english', 'b-ed'], 'EntranceGo original', 'medium', 'published'),
  ((select id from public.subjects where slug = 'english'), 'Choose the correct passive form: ''She writes a letter.''', 'A letter is written by her.', 'A letter is wrote by her.', 'A letter was written by her.', 'A letter has written by her.', 'A', 'Simple present active becomes is/am/are + past participle in the passive.', array['english', 'b-ed'], 'EntranceGo original', 'medium', 'published'),
  ((select id from public.subjects where slug = 'computer-fundamentals'), 'Which of the following is an input device?', 'Printer', 'Scanner', 'Speaker', 'Monitor', 'B', 'A scanner sends data into the computer; the others show or play output.', array['computer-fundamentals', 'b-ed'], 'EntranceGo original', 'easy', 'published'),
  ((select id from public.subjects where slug = 'computer-fundamentals'), 'What is the full form of RAM?', 'Rapid Action Memory', 'Run All Memory', 'Random Access Memory', 'Read Access Memory', 'C', 'RAM stands for Random Access Memory.', array['computer-fundamentals', 'b-ed'], 'EntranceGo original', 'easy', 'published'),
  ((select id from public.subjects where slug = 'computer-fundamentals'), 'Which part is called the brain of the computer?', 'Keyboard', 'Mouse', 'Monitor', 'CPU', 'D', 'The CPU carries out instructions and controls the other parts.', array['computer-fundamentals', 'b-ed'], 'EntranceGo original', 'easy', 'published'),
  ((select id from public.subjects where slug = 'computer-fundamentals'), 'Which keyboard shortcut pastes copied content in Windows?', 'Ctrl + V', 'Ctrl + C', 'Ctrl + P', 'Ctrl + Z', 'A', 'Ctrl + V pastes; Ctrl + C copies, Ctrl + P prints, Ctrl + Z undoes.', array['computer-fundamentals', 'b-ed'], 'EntranceGo original', 'easy', 'published'),
  ((select id from public.subjects where slug = 'computer-fundamentals'), 'Which of the following is a web browser?', 'MS Word', 'Tally', 'Google Chrome', 'Windows 11', 'C', 'Google Chrome is used to open websites.', array['computer-fundamentals', 'b-ed'], 'EntranceGo original', 'medium', 'published'),
  ((select id from public.subjects where slug = 'computer-fundamentals'), 'Which memory keeps its data when the power is switched off?', 'ROM', 'Cache', 'Register', 'RAM', 'A', 'ROM is non-volatile; RAM, cache and registers lose data without power.', array['computer-fundamentals', 'b-ed'], 'EntranceGo original', 'medium', 'published')
